steps_ahead = len(code)//2
same = []
for i in range(len(code)):
    if i + steps_ahead >= len(code):
        if code[i] == code[steps_ahead-(len(code)-i)]:
            same.append(int(code[i]))
    else:
        if code[i] == code[i+steps_ahead]:
            same.append(int(code[i]))
print(sum(same))